  "ui.2b6d3320e661": [
    "支持 PDF、Word（DOCX）、Excel（XLS/XLSX）、PowerPoint（PPTX）、TXT、CSV、MD，每份附件最大 10 MB。图片和扫描件暂不支持文字识别。较长文件只搜索已提取的部分，结果会标注读取范围。成功提取的文字会缓存在本机，加快后续搜索；附件内容变化后会重新读取。",
    "Supports PDF, Word (DOCX), Excel (XLS/XLSX), PowerPoint (PPTX), TXT, CSV, and MD, up to 10 MB each. Images and scans do not support OCR yet. Long files are searched only within extracted text; results show the reading scope. Extracted text is cached locally and refreshed when content changes."
  ],
