  "ui.9a511ccb0c3c": [
    "支持 Excel .xlsx 和 CSV。自动识别姓名、邮箱、部门、工号和电话等字段；导入前会显示新增、变化及冲突。",
    "Supports Excel .xlsx and CSV. Identifies names, emails, departments, employee IDs, and phone numbers; previews additions, changes, and conflicts before import."
  ],
  "ui.66cb68ee6bb6": [
    "导入和更新只影响当前邮箱的通讯录。没有有效邮箱的记录直接忽略，不会按工号匹配或补配邮箱。",
    "Import and updates affect only this account's contacts. Records without valid emails are ignored; employee IDs are not used to match or infer emails."
  ],
  "ui.50f9104c34fa": [
    "默认以现有通讯录为准，仅补全空白资料。个人分组、常用标记和个人备注会保留；文件里的空白不会清除已有资料。",
    "Existing contacts take priority; only blanks are filled by default. Personal groups, favorites, and notes are kept. Blank file fields do not clear existing details."
  ],
