  "guide.topic.outbox.action": "打开任务与发件箱",
  "guide.topic.todos.title": "待办、提醒与日历",
  "guide.topic.todos.desc": "按期限处理任务，核对来源邮件和会议时间。",
  "guide.topic.todos.location": "顶部 → 待办；待办 → 日历文件",
  "guide.topic.todos.step1": "按今天、已逾期、以后或未安排筛选待办；编辑标题，在安排入口设置截止、跟进与提醒，并从来源邮件核对内容。",
  "guide.topic.todos.step2": "完成任务后停止提醒并保留记录。批量操作只影响当前视图中的选择；系统通知权限与提醒时间需要分别配置。",
  "guide.topic.todos.step3": "日历文件可读取邮件中的 ICS 邀请或导入 ICS 预览，核对时区与时间后导出。接受或拒绝会准备回复草稿，仍需确认发送。",
  "guide.topic.todos.action": "打开待办",
  "guide.topic.brief.title": "日报与工作简报",
  "guide.topic.brief.desc": "汇总已同步信息，再核对今天的任务与重点。",
  "guide.topic.brief.location": "顶部 → 今日日报；小邮 → 工作简报",
  "guide.topic.brief.step1": "今日日报汇总当前邮箱的邮件与待办；需要生成内容时先确认 AI 服务可用。结果以本机已同步信息为范围。",
  "guide.topic.brief.step2": "小邮的工作简报可按执行或决策视角查看今天先做、等待反馈和待你确认的线索，不覆盖聊天记录。",
  "guide.topic.brief.step3": "从简报回到原邮件核对，再添加或调整待办。未同步邮件、自动识别的线索或未记录的回复不能代表实际进展。",
  "guide.topic.brief.action": "打开今日日报",
  "guide.topic.assistant.title": "AI 服务与小邮助手",
  "guide.topic.assistant.desc": "配置模型，选择邮件或附件作为本次参考。",
  "guide.topic.assistant.location": "设置 → AI 服务；右下角 → 小邮",
  "guide.topic.assistant.step1": "AI 服务中选择服务商、填写 API 地址、模型名称和 API Key，先测试连接再保存；页头可查看本机记录的模型用量。",
  "guide.topic.assistant.step2": "在小邮中选择参考邮件，提问总结重点、整理待办或准备回复。可选择附件先预览再分析，读取范围与不支持格式会有提示。",
  "guide.topic.assistant.step3": "支持的表格、文档或表单可请求填写并准备回复；先核对字段与生成文件。小邮准备的草稿仍需人工检查并确认发送。",
  "guide.topic.assistant.action": "配置 AI 服务",
  "guide.topic.phone.title": "手机聊天控制邮件",
  "guide.topic.phone.desc": "连接本人微信或钉钉，先预览回复再确认。",
  "guide.topic.phone.location": "设置 → 手机控制",
  "guide.topic.phone.step1": "微信通过二维码连接；钉钉使用应用机器人配置。选择允许控制的邮箱并保存，显示已连接后在本人单聊中发送帮助。",
  "guide.topic.phone.step2": "可询问最新邮件、未读邮件和今天待办，按序号查看，再回复当前邮件。回复先生成预览，需使用有效的一次性编号确认发送。",
  "guide.topic.phone.step3": "电脑须开机联网，MailAI 须保持运行。手机切换邮箱不改变电脑当前邮箱；邮件内容会经过所选聊天平台。",
  "guide.topic.phone.action": "设置手机控制",
  "guide.topic.security.title": "安全检测与处置",
  "guide.topic.security.desc": "查看风险依据，用反馈修正误报与漏报。",
  "guide.topic.security.location": "顶部 → 安全 → 处置策略／安全看板／规则中心",
  "guide.topic.security.step1": "首次使用建议选择仅观察，核对检测结果后使用人工确认，再按需要启用自动处置；不同模式会影响高风险邮件的处理方式。",
  "guide.topic.security.step2": "阅读邮件时展开风险提示核对身份、链接和附件证据，使用反馈标记误报、漏报或确认结果。",
  "guide.topic.security.step3": "安全看板查看趋势与处置记录；规则中心调整启停、权重和阈值。白名单会减少常规误报，但严重风险仍可能提醒。",
  "guide.topic.security.action": "打开规则中心",
  "guide.topic.import.title": "导入 Foxmail 旧邮件",
  "guide.topic.import.desc": "扫描去重后导入，历史邮件保留在本地归档。",
  "guide.topic.import.location": "设置 → 数据与维护 → 从 Foxmail 导入",
  "guide.topic.import.step1": "先在原客户端导出完整 EML、MBOX 或邮件目录，再核对 MailAI 中的目标邮箱并选择文件。",
  "guide.topic.import.step2": "先扫描并去重，查看新增、重复和问题文件，再点击导入缺少的邮件；不会覆盖原客户端邮件，也不会上传服务器。",
  "guide.topic.import.step3": "完成后从目标邮箱的本地归档阅读。暂停、重启或失败后，可从最近导入记录继续；问题文件可重新导出并重试。",
  "guide.topic.import.action": "进入数据与维护",
  "guide.topic.backup.title": "备份、换机与服务器清理",
  "guide.topic.backup.desc": "区分本机恢复、设备迁移和服务器空间释放。",
  "guide.topic.backup.location": "设置 → 数据与维护",
  "guide.topic.backup.step1": "本机备份用于当前设备恢复，可在备份记录中另存为或恢复；恢复前会保留安全副本。",
  "guide.topic.backup.step2": "换电脑使用导出到新设备和从旧设备导入，可限定导出日期并设置迁移密码。新设备需重新配置邮箱授权码和模型密钥。",
  "guide.topic.backup.step3": "清理服务器邮件时，先选择范围并预览，再核对列表和邮箱地址。执行前会备份，本机邮件保留；网页版和其他设备可能不再显示，恢复本地备份不会重新上传。",
  "guide.topic.backup.action": "管理备份与迁移",
  "guide.empty.title": "没有找到相关帮助",
  "guide.empty.copy": "换一个关键词试试，或返回全部主题。",
  "guide.empty.action": "查看全部帮助",
  "guide.faq.title": "常见问题",
  "guide.faq.ai-unavailable.title": "小邮没有回答或模型连接失败？",
  "guide.faq.ai-unavailable.copy": "在 AI 服务中核对服务商、API 地址、模型名称和 Key，再点击测试连接；仍失败时到数据与维护运行诊断，按失败项查看建议。模型故障不影响阅读已同步邮件。",
  "guide.faq.ai-unavailable.action": "检查 AI 服务",
  "guide.faq.missing-mail.title": "为什么搜不到邮件或附件？",
  "guide.faq.missing-mail.copy": "先检查搜索的账号、文件夹、日期和筛选条件，再核对同步状态。邮件搜索只覆盖已同步内容；Foxmail 历史需先导入。附件内容搜索不包含扫描图片，较长文件可能只读取部分文字。",
  "guide.faq.missing-mail.action": "检查邮箱账号",
  "guide.faq.uncertain-send.title": "发送失败，能直接重新发送吗？",
  "guide.faq.uncertain-send.copy": "先在任务与发件箱核对阶段。若提示结果需要核对，请先查看已发送邮件或网页邮箱，确认是否送达再操作，避免重复发信；尚未开始的定时任务可调整或取消。",
  "guide.faq.uncertain-send.action": "运行诊断",
  "guide.faq.privacy.title": "邮件和附件会发送到哪里？",
  "guide.faq.privacy.copy": "邮件与界面偏好保存在本机。启用云端 AI 后，自动分析及小邮功能会按任务发送所需内容到所选模型服务；大附件分享和手机控制分别经过存储服务与聊天平台。可在关于与隐私查看说明，并按需要使用本地模型。",
  "guide.faq.privacy.action": "查看隐私说明",
