  "ui.91b6c88a8772": "邮箱和模型分别配置。启用后，小邮可以总结邮件、整理待办、辅助写信。",
  "ui.6e48e41be7f4": "没有 API Key？",
  "ui.b04994f584b9": "API Key 是模型服务的访问密钥，与邮箱授权码不同。请向企业管理员获取服务地址、模型名称和 API Key，或从所选模型服务商获取。",
  "ui.5c9947093207": "使用 AI 时，相关邮件内容会发送至配置的模型服务。验证连接会发送简短请求，可能产生服务费用。",
