  "ui.cca888cce2e8": "支持的文件与搜索范围",
  "ui.2b6d3320e661": "支持 PDF、Word（DOCX）、Excel（XLS/XLSX）、PowerPoint（PPTX）、TXT、CSV、MD，每份附件最大 10 MB。图片和扫描件暂不支持文字识别。较长文件只搜索已提取的部分，结果会标注读取范围。成功提取的文字会缓存在本机，加快后续搜索；附件内容变化后会重新读取。",
  "ui.8a18aa905cba": "不记得文件名？试试文件里的文字",
  "ui.a600c40446ad": "例如合同编号、项目名称、客户名称。搜索结果可直接预览，并定位到来源邮件。",
  "ui.38f08532f33d": "合同编号",
