  "ui.c51105fd1a93": "没有附件",
  "ui.74e3b3b1b04e": "下面是同名文件候选，不一定属于同一材料。请根据来源邮件核对，再选择两份查看文字差异。",
  "ui.0bc74213dba1": "正在查找同名附件…",
  "ui.8a9ad8f9ddcf": "没有其他同名附件",
  "ui.50c0585d008b": "可以预览原文件，或返回附件中心查找其他文件。",
  "ui.9ac6d364aa41": "文件 A",
  "ui.aba8f0d0e319": "文件 B",
  "ui.89708cbd8fc2": "我已核对来源，这两份文件属于同一材料",
  "ui.f30dcd2ace31": "不同月份的报表或不同项目的同名附件，差异通常不代表修订。",
  "ui.491269b3ec34": "查看文字差异",
  "ui.0b8d69225e8d": "仅比较可提取的文字。不会判断哪份有效，也不汇总金额；Excel 不重算公式。",
  "ui.bdbace2402dc": "查看两份文件的读取范围",
  "ui.e9b5058c6501": "文件 ___MUI_SLOT_0___",
  "ui.e1dca25800f9": "管理邮件里的大文件下载链接",
  "ui.cfc2ef87342c": "大文件上传到你配置的腾讯云存储，再把下载链接插入邮件。这里只显示已上传文件，普通邮件附件不会自动出现在这里。",
  "ui.3b3f784aab6a": "链接到期后会怎样？",
  "ui.a1a70a4996cb": "收件人将无法使用已到期的链接。重新生成后，需要把新链接发给收件人；旧邮件不会自动更新。上传的文件仍在你的存储桶内。",
  "ui.b525d731a0db": "复制下载链接",
  "ui.6f086b9c567d": "生成新链接 · 7 天",
  "ui.84c0b545d3df": "还没有分享过大文件",
  "ui.23d319d141ab": "点击上方按钮，在写信时选择文件、设置有效期，上传后将下载链接插入正文。首次使用需要连接你自己的腾讯云存储；也可把已有网盘链接直接粘贴进邮件。",
  "ui.bcd020da6793": "写信的“发送安排”中可设置未回复提醒。仅对成功发送的邮件计时；同步到关联回复后取消提醒。未同步的回复无法判断，不会自动发送催办邮件。",
  "ui.6da097eb22f3": "新的跟进时间",
  "ui.f3b07169f705": "取消提醒",
  "ui.4e12454a1dd1": "计划发送时间",
  "ui.15c8e0a5b893": "电脑联网且 MailAI 运行时执行；退出期间无法准时发送。调整时间不会修改邮件内容。",
  "ui.f0f609f1e296": "保存时间",
  "ui.961ddaf780e3": "导入 ICS 日历文件",
  "ui.5c56bfb6da4b": "核对后创建日历事件：",
  "ui.c3405f8c7d9d": "标题",
  "ui.1b1b03a8147d": "开始时间（本地）",
  "ui.7a5c755878e3": "结束时间（本地）",
  "ui.253ac66fb8e1": "地点",
  "ui.21e07454f9db": "导入文件只预览邀请；可下载原始 ICS 导入系统日历。接受/拒绝需核对并发送日历回复，对方服务可能不自动更新。手动创建的日期由你核对填写。",
  "ui.2825997ff294": "接受并起草回复",
  "ui.724c0db4409a": "拒绝并起草回复",
  "ui.202d91087108": "没有 ICS 邀请，可导入文件或手动安排事件。",
  "ui.e24dc0e8d944": "并列核对同一会话的明确日期与金额。不同事项和报价口径可能不同，片段不能代替最终确认。",
  "ui.675b05844efa": "AI 核对会将最多 12 封关联往来的正文发送给已配置模型，可能产生 API 用量；附件不包含在本次参考中。",
  "ui.5e5437735a6b": "其中邮件存在风险线索，请先核实来源。",
  "ui.ac54a02394fe": "没有得到能在原文定位的变化候选；不能据此判定没有变化。",
  "ui.69db9adc92f4": "___MUI_SLOT_0___ · ___MUI_SLOT_1___ · 待核对",
  "ui.396c6be93bc6": "这封邮件应放在哪个视图？",
  "ui.195522d4d65e": "同时应用于该发件人的后续邮件",
